INSERT INTO `Boat` VALUES (297,NULL,'boat brokers product images/poppy/poppy02.jpg',1,'2026-09-10 09:46:27.334','2026-09-10 09:46:27.334','Single','No','Cooking and water heater','Not stated','Large rectangular shower',NULL,'4ft 2in','Cassette toilet','Yes – with vanity cupboard & mirror','N/a','1 x starter 110Ah & 2 x leisure 110Ah','N/A',NULL,NULL,'N/A','Not known','POPPY',NULL,'Not known','No','Teddesley Boats','White painted vertically mounted planks','White painted ply','No','N/A','£17,950',NULL,'63972','150 litres approx.','No','Not known',NULL,'Lister 3 cylinder – air cooled',NULL,'Not known but runs well','Tedddesley Boats','Laminate','4 burner Spinflo hob & grill',NULL,'No','7ft 3in','No','No','No','1x 13kg stern lockers (no bottle included)','Lister','N/A','Not known','Teddesley Boats','Oak effect laminate mounted vertically to hull sides','Not stated',NULL,'6ft (centre)','No','No','Not known but runs well','48ft','TBC','12V',NULL,'POPPY','Various','2 + 2','48ft Traditional Narrowboat – Project with Great Potential A fantastic opportunity to create your own boat with this 48ft traditional stern narrowboat, built by Teddesley Boats in 1977. Spacious, clean and open-plan inside with a fitted galley, shower room with cassette toilet and solid fuel stove. Powered by a characterful 3-cylinder air-cooled Lister diesel engine which runs well. The cabin sides and roof have recently been repainted, providing a great starting point for the new owner to complete the interior to their own taste. An ideal project for the skilled DIYer or enthusiastic amateur and a very affordable entry into life on the water, whether as a leisure boat or potential liveaboard. Plenty of space, plenty of character and bags of potential.','2 +',NULL,'No','19ft','Open plan','No','Yes','Paloma water heater',NULL,'Traditional','No',NULL,'Integral steel','350 litres approx.','Quick release under rear deck','Combination of single glazed windows & port holes','1977','Narrowboats','N/A',0,0,0,17